const __pageData = JSON.parse('{"title":"Instructor answer key — Week 04","description":"","frontmatter":{"search":false,"prev":false,"next":false},"headers":[],"relativePath":"materials/week-04/instructor/answers.md","filePath":"materials/week-04/instructor/answers.md"}');
